import os, subprocess, hashlib, shutil
def tree(root):
    h = {}
    for d, dirs, fs in os.walk(root):
        for f in fs + [x for x in dirs if os.path.islink(os.path.join(d,x))]:
            p = os.path.join(d, f); rel = os.path.relpath(p, root)
            h[rel] = "L:"+os.readlink(p) if os.path.islink(p) else hashlib.sha1(open(p,'rb').read()).hexdigest()
    return h
S = tree("../extr/src2")
for n in ("w4k","w1k","w3"):
    gone = {l.split("/")[-1].strip() for l in open("cmds_"+n)}
    exp = {k:v for k,v in S.items() if not (k.startswith("big/") and k[4:] in gone)}
    r = subprocess.run(["e2fsck","-fn",n+".img"],capture_output=True,text=True)
    shutil.rmtree("out", ignore_errors=True); os.mkdir("out")
    subprocess.run(["debugfs","-R","rdump / out",n+".img"],capture_output=True)
    got = tree("out"); got.pop("lost+found",None)
    diff=[k for k,v in exp.items() if got.get(k)!=v]; extra=[k for k in got if k not in exp]
    print(n, os.path.getsize(n+".img")//1048576, "MB", "e2fsck", r.returncode, "fark", len(diff), "fazla", len(extra))
EOF

