        size = struct.unpack_from("<I", self._root, 10)[0]
        return IsoEntry(name="", is_dir=True, size=size, extents=[(ext, size)])

    def listdir(self, path: str = "/") -> List[IsoEntry]:
        key = "/" + path.strip("/")
        hit = self._cache.get(key)
        if hit is not None:
            return hit
